insert into public.topics (id, domain, domain_name, domain_weight, name, sort_order, learn_url) values
  ('cloud-computing', 1, 'Describe cloud concepts', '25-30%', 'Cloud computing', 1, 'https://learn.microsoft.com/en-us/training/paths/microsoft-azure-fundamentals-describe-cloud-concepts/'),
  ('cloud-benefits', 1, 'Describe cloud concepts', '25-30%', 'Benefits of cloud services', 2, 'https://learn.microsoft.com/en-us/training/paths/microsoft-azure-fundamentals-describe-cloud-concepts/'),
  ('service-types', 1, 'Describe cloud concepts', '25-30%', 'Cloud service types (IaaS, PaaS, SaaS)', 3, 'https://learn.microsoft.com/en-us/training/paths/microsoft-azure-fundamentals-describe-cloud-concepts/'),
  ('core-architecture', 2, 'Describe Azure architecture and services', '35-40%', 'Core architectural components', 4, 'https://learn.microsoft.com/en-us/training/paths/azure-fundamentals-describe-azure-architecture-services/'),
  ('compute-networking', 2, 'Describe Azure architecture and services', '35-40%', 'Compute and networking', 5, 'https://learn.microsoft.com/en-us/training/paths/azure-fundamentals-describe-azure-architecture-services/'),
  ('storage', 2, 'Describe Azure architecture and services', '35-40%', 'Storage services', 6, 'https://learn.microsoft.com/en-us/training/paths/azure-fundamentals-describe-azure-architecture-services/'),
  ('identity-security', 2, 'Describe Azure architecture and services', '35-40%', 'Identity, access and security', 7, 'https://learn.microsoft.com/en-us/training/paths/azure-fundamentals-describe-azure-architecture-services/'),
  ('cost-management', 3, 'Describe Azure management and governance', '30-35%', 'Cost management', 8, 'https://learn.microsoft.com/en-us/training/paths/describe-azure-management-governance/'),
  ('governance-compliance', 3, 'Describe Azure management and governance', '30-35%', 'Governance and compliance', 9, 'https://learn.microsoft.com/en-us/training/paths/describe-azure-management-governance/'),
