  ('monitoring', 3, 'Describe Azure management and governance', '30-35%', 'Monitoring tools', 11, 'https://learn.microsoft.com/en-us/training/paths/describe-azure-management-governance/')
insert into public.questions (id, topic_id, question, options, correct_index, explanation, difficulty) values
  ('cc-01', 'cloud-computing', 'A retailer rents extra computing capacity for its two-week holiday sale and stops paying for it when the sale ends. Which model does this describe?', '["Capital expenditure (CapEx)", "Consumption-based (pay-as-you-go) model", "A fixed three-year hardware lease", "Private cloud ownership"]'::jsonb, 1, 'In the consumption-based model you pay only for the resources you use, when you use them. There is no upfront hardware purchase and no paying for idle capacity once the peak has passed.', 1),
  ('cc-02', 'cloud-computing', 'Under the shared responsibility model, which item is ALWAYS the customer''s responsibility, whatever the cloud service type?', '["Physical datacenter security", "Firmware on the physical hosts", "Their information and data", "Physical network cabling"]'::jsonb, 2, 'The provider always owns the physical datacenter, network and hosts. The customer always owns their data, the devices that connect, and the accounts and identities that can reach their cloud resources.', 2),
  ('cc-03', 'cloud-computing', 'A hospital must keep patient records in its own datacenter but wants to use public cloud capacity for seasonal demand spikes. Which cloud model fits best?', '["Public cloud only", "Private cloud only", "Hybrid cloud", "Software as a Service"]'::jsonb, 2, 'A hybrid cloud combines a private environment with a public cloud. Sensitive workloads stay in the private environment while the public cloud absorbs temporary demand.', 1),
  ('cc-04', 'cloud-computing', 'Which is a typical drawback of a private cloud compared with a public cloud?', '["Your data shares hardware with other tenants", "You have less control over security", "You cannot run it in your own datacenter", "Higher cost, because you buy and maintain the hardware"]'::jsonb, 3, 'A private cloud gives you full control, but your organisation pays for and maintains the hardware, so it usually costs more and scales less quickly than a public cloud.', 2),
  ('cc-05', 'cloud-computing', 'Which statement best describes serverless computing?', '["There are no physical servers involved anywhere", "You write the code, and the platform provisions, scales and runs the infrastructure, charging for actual usage", "You manage the operating system but not the application", "It can only run inside an on-premises datacenter"]'::jsonb, 1, 'Serverless does not mean there are no servers. It means you do not manage them. The platform handles provisioning and scaling, and you are typically billed for execution time or requests.', 2),
  ('cc-06', 'cloud-computing', 'A start-up wants to launch a product quickly without buying any hardware upfront. Which option is the best fit?', '["Building a private datacenter", "Public cloud", "Buying servers and colocating them", "Waiting for a hardware refresh cycle"]'::jsonb, 1, 'Public cloud removes the upfront capital cost. You can provision resources in minutes and pay for them as an operating expense.', 1),
  ('cb-01', 'cloud-benefits', 'Which statement describes high availability in the cloud?', '["The ability to resize a virtual machine", "The ability to estimate monthly costs in advance", "Keeping services running with minimal downtime, often backed by a service level agreement (SLA)", "The ability to move workloads to another cloud provider"]'::jsonb, 2, 'High availability is about keeping workloads accessible. Providers express it as an SLA, such as a percentage of uptime they commit to.', 1),
  ('cb-02', 'cloud-benefits', 'Traffic to a web app suddenly increases tenfold, and you add more identical instances to share the load. What is this called?', '["Vertical scaling", "Horizontal scaling (scale out)", "Geo-replication", "Right-sizing"]'::jsonb, 1, 'Horizontal scaling adds more instances of a resource. Vertical scaling instead makes one instance more powerful.', 1),
  ('cb-03', 'cloud-benefits', 'Which action is an example of vertical scaling?', '["Adding five more virtual machines behind a load balancer", "Increasing the CPU and memory of an existing virtual machine", "Deploying the app to a second region", "Deleting unused resources"]'::jsonb, 1, 'Vertical scaling (scale up or down) changes the capability of a single resource, for example moving a VM to a larger size.', 1),
  ('cb-04', 'cloud-benefits', 'A system can recover from failures and keep functioning. Which cloud benefit does this describe?', '["Elasticity", "Reliability", "Governance", "Cost predictability"]'::jsonb, 1, 'Reliability is the ability of a system to recover from failures and continue to work. It is a pillar of the Azure Well-Architected Framework.', 2),
  ('cb-05', 'cloud-benefits', 'Which cloud benefit lets you use templates so that every deployed resource meets your organisation''s standards?', '["Latency", "Elasticity", "Governance", "Portability"]'::jsonb, 2, 'Governance in the cloud uses templates, policies and auditing so that deployments meet technical and regulatory standards, and non-compliant resources can be flagged.', 2),
  ('cb-06', 'cloud-benefits', 'Which of these is an example of management OF the cloud (as opposed to management IN the cloud)?', '["Creating a VM with the Azure CLI", "Browsing resources in the web portal", "Automatically scaling resources up and down based on demand", "Running a PowerShell script"]'::jsonb, 2, 'Management of the cloud covers what the cloud does for you, such as autoscaling, template deployment and automatic health monitoring. Management in the cloud is the tooling you use: portal, CLI, APIs and PowerShell.', 3),
  ('st-01', 'service-types', 'A team is migrating a legacy application that needs a specific operating system configuration. Which service type gives them the control they need?', '["Infrastructure as a Service (IaaS)", "Platform as a Service (PaaS)", "Software as a Service (SaaS)", "None, the cloud cannot host legacy apps"]'::jsonb, 0, 'IaaS gives you virtual machines and networking that you configure yourself, including the operating system. That control suits lift-and-shift migrations of existing applications.', 1),
  ('st-02', 'service-types', 'Developers want to deploy a web API without patching servers or managing the operating system. Which service type fits?', '["IaaS", "On-premises hosting", "Software as a Service", "Platform as a Service (PaaS)"]'::jsonb, 3, 'PaaS provides a managed environment for building and deploying applications. The provider runs the operating system, runtime and underlying infrastructure.', 1),
  ('st-03', 'service-types', 'Employees use a hosted email and calendar service that the provider manages entirely. Which service type is this?', '["IaaS", "PaaS", "SaaS", "Hybrid"]'::jsonb, 2, 'SaaS delivers a finished application. The provider manages everything from infrastructure to the app, and you manage your data, users and settings.', 1),
  ('st-04', 'service-types', 'In which service type does the customer take on the MOST management responsibility?', '["SaaS", "PaaS", "IaaS", "They are all identical"]'::jsonb, 2, 'With IaaS you manage the operating system, patches, middleware, apps and data. Responsibility shifts toward the provider as you move to PaaS and then SaaS.', 2),
  ('st-05', 'service-types', 'Which statement about PaaS is correct?', '["The customer manages the physical hardware", "The provider manages the OS and runtime, and the customer manages application code and data", "The customer receives a complete finished application", "The customer must install operating system patches"]'::jsonb, 1, 'In PaaS the provider takes care of the infrastructure, operating systems and runtimes. You focus on your code and data.', 2),
  ('st-06', 'service-types', 'Which of these is an example of an IaaS offering?', '["Azure App Service", "Microsoft 365", "Azure Virtual Machines", "Azure Functions"]'::jsonb, 2, 'Azure Virtual Machines lets you rent virtual servers and manage the OS yourself, which is IaaS. App Service and Functions are PaaS or serverless, and Microsoft 365 is SaaS.', 2),
  ('ca-01', 'core-architecture', 'What is an Azure region?', '["A single server rack", "A geographic area containing one or more datacenters connected by a low-latency network", "A group of subscriptions", "A virtual network boundary"]'::jsonb, 1, 'A region is a set of datacenters deployed within a latency-defined perimeter and connected through a dedicated regional low-latency network. You choose a region when you deploy most resources.', 1),
  ('ca-02', 'core-architecture', 'Which statement best describes availability zones?', '["Groups of regions in the same country", "Physically separate locations within a region, each with independent power, cooling and networking", "Logical groupings of subscriptions", "Another name for virtual networks"]'::jsonb, 1, 'Availability zones protect against datacenter-level failures. Each zone is a separate physical location within a region, so a problem in one zone does not take down the others.', 2),
  ('ca-03', 'core-architecture', 'Why does Azure pair regions within a geography?', '["Every Azure service replicates all data between the pair automatically", "To support disaster recovery: recovery of one region in each pair is prioritised in a wide outage, and planned updates are rolled out one region at a time", "To double the price of resources", "So that subscriptions can only be used in two regions"]'::jsonb, 1, 'Region pairs help with resilience. Azure prioritises restoring one region of each pair during a broad outage and applies platform updates sequentially. Replication of your data still depends on the service and the options you choose.', 3),
  ('ca-04', 'core-architecture', 'Which is the correct hierarchy, from highest level to lowest?', '["Subscription, management group, resource group, resource", "Resource group, subscription, management group, resource", "Management group, subscription, resource group, resource", "Resource, resource group, subscription, management group"]'::jsonb, 2, 'Management groups contain subscriptions, subscriptions contain resource groups, and resource groups contain resources. Policies and access assigned higher up are inherited downward.', 2),
  ('ca-05', 'core-architecture', 'Which statement about Azure resource groups is true?', '["A resource can belong to several resource groups at the same time", "Resource groups can be nested inside one another", "A resource belongs to exactly one resource group at a time", "Deleting a resource group leaves its resources untouched"]'::jsonb, 2, 'Each resource lives in exactly one resource group. Resource groups cannot be nested, and deleting one deletes every resource inside it.', 2),
  ('ca-06', 'core-architecture', 'You need to apply the same Azure Policy to ten different subscriptions in one action. Which container should you use?', '["A resource group", "A management group", "A virtual network", "An availability set"]'::jsonb, 1, 'Management groups sit above subscriptions. Assigning a policy or access rule to a management group applies it to every subscription beneath it.', 2),
  ('cn-01', 'compute-networking', 'Which Azure compute option runs your code in response to events, bills per execution and needs no server management?', '["Azure Virtual Machines", "Azure Functions", "Azure Virtual Desktop", "An availability set"]'::jsonb, 1, 'Azure Functions is event-driven serverless compute. You supply the code, and Azure runs and scales it, billing for what executes.', 1),
  ('cn-02', 'compute-networking', 'Which resource lets you automatically add or remove identical VMs as load changes?', '["Availability set", "Virtual Machine Scale Sets", "Azure DNS", "Azure File Sync"]'::jsonb, 1, 'Virtual Machine Scale Sets manage a group of load-balanced, identical VMs and can scale the number of instances up or down automatically.', 2),
  ('cn-03', 'compute-networking', 'What is the purpose of an availability set?', '["To scale VMs automatically", "To spread VMs across fault domains and update domains so one hardware failure or maintenance event does not take them all down", "To connect two virtual networks", "To store VM backups"]'::jsonb, 1, 'An availability set arranges VMs across separate fault domains (hardware) and update domains (maintenance), reducing the impact of a single failure or planned update.', 3),
  ('cn-04', 'compute-networking', 'Which service gives a private, dedicated connection from an on-premises network to Azure that does NOT travel over the public internet?', '["VPN Gateway", "Azure DNS", "ExpressRoute", "VNet peering"]'::jsonb, 2, 'ExpressRoute uses a private connection through a connectivity provider. A VPN Gateway also connects on-premises networks but sends encrypted traffic over the public internet.', 2),
  ('cn-05', 'compute-networking', 'What does virtual network (VNet) peering do?', '["Encrypts data stored in a VNet", "Connects two virtual networks so resources can communicate privately over the Microsoft backbone network", "Translates domain names to IP addresses", "Creates a backup of a VNet"]'::jsonb, 1, 'Peering links virtual networks so their resources talk using private IP addresses, with traffic staying on the Microsoft backbone rather than the public internet.', 2),
  ('cn-06', 'compute-networking', 'What is a private endpoint?', '["A public IP address for a virtual machine", "A network interface in your virtual network with a private IP address that connects you privately to an Azure service", "A firewall rule that blocks all traffic", "A type of storage account"]'::jsonb, 1, 'A private endpoint brings an Azure service, such as a storage account, into your virtual network with a private IP address, so traffic does not need to use the public endpoint.', 3),
  ('cn-07', 'compute-networking', 'How do containers differ from virtual machines?', '["Containers each include a full guest operating system", "Containers share the host operating system kernel, so they are lighter and start faster", "Containers cannot run web apps", "Containers always require a physical server"]'::jsonb, 1, 'Containers package an app and its dependencies but share the host OS kernel. This makes them smaller and faster to start than VMs, which each carry a full guest operating system.', 2),
  ('sg-01', 'storage', 'Which Azure Storage service provides fully managed file shares that can be accessed over SMB?', '["Azure Blob Storage", "Azure Files", "Azure Queue Storage", "Azure Table Storage"]'::jsonb, 1, 'Azure Files offers managed file shares in the cloud that you can mount from Windows, Linux and macOS using the SMB protocol (and NFS for some tiers).', 1),
  ('sg-02', 'storage', 'Which storage service is best for large amounts of unstructured data such as images, video and backups?', '["Azure Blob Storage", "Azure Queue Storage", "Azure Files", "Azure Disk Storage"]'::jsonb, 0, 'Blob Storage is optimised for massive amounts of unstructured data such as images, documents, video and backup files.', 1),
  ('sg-03', 'storage', 'Which access tier has the lowest storage cost for data that is rarely accessed and can tolerate hours of retrieval delay?', '["Hot", "Cool", "Cold", "Archive"]'::jsonb, 3, 'The Archive tier is the cheapest to store but the data is offline. It must be rehydrated before use, which can take hours. Hot suits frequent access, with Cool and Cold in between.', 2),
  ('sg-04', 'storage', 'Which redundancy option copies your data synchronously across three availability zones in the primary region?', '["Locally redundant storage (LRS)", "Zone-redundant storage (ZRS)", "Geo-redundant storage (GRS)", "The Archive access tier"]'::jsonb, 1, 'ZRS replicates data across three availability zones in one region, protecting against a datacenter failure. LRS keeps three copies inside a single datacenter.', 2),
  ('sg-05', 'storage', 'Which option helps protect your data from a complete regional outage?', '["Locally redundant storage (LRS)", "Zone-redundant storage (ZRS)", "Geo-redundant storage (GRS)", "The Hot access tier"]'::jsonb, 2, 'GRS also copies data to a secondary region far from the primary, so the data survives the loss of the whole primary region. LRS and ZRS keep data in one region.', 2),
  ('sg-06', 'storage', 'Which command-line tool is optimised for copying data to and from Azure storage accounts?', '["AzCopy", "Azure File Sync", "Azure Data Box", "Azure Migrate"]'::jsonb, 0, 'AzCopy is a command-line utility for fast, scriptable transfers to and from Blob and File storage. Storage Explorer is the graphical equivalent.', 2),
  ('sg-07', 'storage', 'A company has hundreds of terabytes to move to Azure but only a slow internet link. Which option is best?', '["Azure Data Box (a physical transfer device)", "Azure DNS", "A larger virtual machine", "Azure Advisor"]'::jsonb, 0, 'Azure Data Box is a physical appliance you fill with data and ship to Microsoft, which uploads it for you. It is designed for very large transfers where network speed is a bottleneck.', 2),
  ('sg-08', 'storage', 'Which service keeps an on-premises Windows file server in sync with Azure Files?', '["Azure Migrate", "AzCopy", "Azure File Sync", "Azure Backup vault"]'::jsonb, 2, 'Azure File Sync turns a Windows Server into a cache of an Azure file share, keeping local and cloud copies in sync. Azure Migrate is for assessing and moving servers and workloads.', 3),
  ('is-01', 'identity-security', 'Which Azure service provides cloud-based identity and access management for users and apps?', '["Microsoft Entra ID", "Azure DNS", "Azure Monitor", "Azure Policy"]'::jsonb, 0, 'Microsoft Entra ID (formerly Azure Active Directory) is Microsoft''s cloud identity and access management service.', 1),
  ('is-02', 'identity-security', 'Which sign-in is an example of multifactor authentication?', '["A password followed by a second password", "A password followed by approving a prompt on your phone", "Two different usernames", "A very long passphrase on its own"]'::jsonb, 1, 'MFA combines factors from different categories: something you know (password), something you have (phone) and something you are (biometric). Two passwords are still one category.', 2),
  ('is-03', 'identity-security', 'A support engineer must be able to restart virtual machines in one resource group but do nothing else. What should you use?', '["A resource lock", "Azure role-based access control (RBAC) with a role assigned at that resource group", "A tag on the VMs", "A pricing calculator estimate"]'::jsonb, 1, 'RBAC grants permissions by assigning roles at a scope. Scoping the role to one resource group follows the principle of least privilege.', 2),
  ('is-04', 'identity-security', 'You want users to be asked for MFA only when they sign in from outside the corporate network. Which feature do you use?', '["Microsoft Entra Conditional Access", "Azure Advisor", "Resource locks", "Azure Arc"]'::jsonb, 0, 'Conditional Access applies if-then rules to sign-ins. Signals such as location, device or risk decide whether to allow, block or require extra verification like MFA.', 2),
  ('is-05', 'identity-security', 'Which set of principles describes Zero Trust?', '["Trust everything inside the corporate network by default", "Verify explicitly, use least-privilege access and assume breach", "Rely on a single strong perimeter firewall", "Disable all remote access"]'::jsonb, 1, 'Zero Trust treats every request as untrusted until verified. It verifies explicitly, limits access to what is needed, and assumes an attacker may already be inside.', 2),
  ('is-06', 'identity-security', 'What does the defense-in-depth model describe?', '["Relying on one very strong security control", "Using multiple layers of protection, such as physical, identity, perimeter, network, compute, application and data", "Keeping all data in one datacenter", "Encrypting only the network"]'::jsonb, 1, 'Defense in depth layers several protections so that if one layer is breached, the others still slow or stop an attacker.', 2),
  ('is-07', 'identity-security', 'Which service provides security posture management and threat protection for workloads in Azure and hybrid environments?', '["Azure Service Health", "Microsoft Defender for Cloud", "Azure Pricing Calculator", "Azure Cloud Shell"]'::jsonb, 1, 'Microsoft Defender for Cloud assesses your security posture, recommends improvements and provides threat protection across Azure, hybrid and multicloud workloads.', 2),
  ('is-08', 'identity-security', 'What does single sign-on (SSO) let a user do?', '["Use the same password for every website", "Sign in once and access multiple applications without entering credentials again", "Skip authentication entirely", "Share an account with coworkers"]'::jsonb, 1, 'With SSO a user authenticates once with their identity provider and then gets access to multiple apps, reducing password fatigue while keeping central control.', 1),
  ('cm-01', 'cost-management', 'Which factor can change the price of the same virtual machine size?', '["The region where it is deployed", "The name of its resource group", "The tags applied to it", "The display name of the subscription"]'::jsonb, 0, 'Costs vary by region because of local factors such as infrastructure and energy costs. Resource type, size, usage and bandwidth also affect cost, but names and tags do not.', 1),
  ('cm-02', 'cost-management', 'Which tool estimates the cost of Azure resources you are planning to deploy?', '["Azure Advisor", "Azure Pricing Calculator", "Azure Service Health", "Azure Policy"]'::jsonb, 1, 'The Pricing Calculator lets you configure services and see an estimate before you deploy. It estimates planned spend, whereas Cost Management analyses what you actually spend.', 1),
  ('cm-03', 'cost-management', 'Which capability lets you analyse your actual spending, set budgets and receive cost alerts?', '["Microsoft Cost Management", "Azure Cloud Shell", "Azure Arc", "Azure DNS"]'::jsonb, 0, 'Microsoft Cost Management provides cost analysis, budgets and alerts for your actual Azure usage.', 2),
  ('cm-04', 'cost-management', 'You want to see how much each department spends on Azure. What helps most?', '["Applying a tag such as department to resources and grouping costs by that tag", "Deleting the resource groups", "Using a larger VM size", "Enabling a resource lock"]'::jsonb, 0, 'Tags are name-value pairs you attach to resources. In cost analysis you can group or filter by tag to attribute spend to teams, projects or environments.', 2),
  ('cm-05', 'cost-management', 'Which option lowers the price of steady, predictable workloads when you commit to one or three years of use?', '["Azure reservations", "Azure Service Health", "Management groups", "Resource locks"]'::jsonb, 0, 'Azure reservations give a discount compared with pay-as-you-go prices in exchange for a one-year or three-year commitment, which suits stable workloads.', 2),
  ('cm-06', 'cost-management', 'A dev VM is not needed overnight. What stops the compute charges while keeping its disks?', '["Shutting down the operating system from inside the VM", "Stopping (deallocating) the VM in Azure", "Adding a tag called off", "Removing its network interface"]'::jsonb, 1, 'If you only shut down the OS, the VM stays allocated and still incurs compute charges. Stopping it (deallocating) through Azure releases the compute, though you still pay for the disks.', 3),
  ('gc-01', 'governance-compliance', 'Which service lets you create rules, for example allowing resources to be deployed only in approved regions?', '["Azure Policy", "Azure Monitor", "Azure DNS", "AzCopy"]'::jsonb, 0, 'Azure Policy defines and enforces standards for resources, and evaluates how compliant your existing resources are.', 1),
  ('gc-02', 'governance-compliance', 'How can you stop even subscription owners from accidentally deleting a critical resource?', '["Apply a CanNotDelete resource lock", "Add a tag", "Move it to another region", "Use the Pricing Calculator"]'::jsonb, 0, 'Resource locks override user permissions. A CanNotDelete lock lets authorised users read and modify a resource but prevents deletion until the lock is removed.', 2),
  ('gc-03', 'governance-compliance', 'Which service helps you discover, classify and govern data across on-premises, multicloud and SaaS sources?', '["Microsoft Purview", "Azure Advisor", "Azure Virtual Desktop", "Azure Load Balancer"]'::jsonb, 0, 'Microsoft Purview is a data governance and compliance service for mapping, classifying and managing data across your whole estate.', 2),
  ('gc-04', 'governance-compliance', 'What is the key difference between Azure Policy and Azure RBAC?', '["They do exactly the same thing", "Policy controls what resource configurations are allowed, and RBAC controls what actions users are allowed to take", "RBAC controls pricing and Policy controls networking", "Policy only works on-premises"]'::jsonb, 1, 'RBAC answers who can do what. Policy answers what resources may look like, regardless of who is deploying them. Use them together.', 3),
  ('gc-05', 'governance-compliance', 'What does a ReadOnly lock on a resource do?', '["Authorised users can read the resource but cannot modify or delete it", "It encrypts the resource", "It hides the resource from everyone", "It only blocks deletion but allows changes"]'::jsonb, 0, 'A ReadOnly lock is like giving everyone the Reader role on that resource: it can be viewed but not changed or deleted. CanNotDelete allows changes but blocks deletion.', 2),
  ('gc-06', 'governance-compliance', 'You apply a CanNotDelete lock to a resource group. What happens to the resources inside it?', '["Nothing, the lock applies to the group only", "They inherit the lock, so they cannot be deleted either", "They are deleted", "They are moved to a new subscription"]'::jsonb, 1, 'Locks are inherited by child resources. A lock on a resource group or subscription also protects everything inside it.', 3),
  ('mt-01', 'management-tools', 'Which tool is a web-based console for creating and managing Azure resources?', '["Azure portal", "AzCopy", "Azure Data Box", "Azure Migrate"]'::jsonb, 0, 'The Azure portal is the browser-based graphical interface for managing resources, dashboards and subscriptions.', 1),
  ('mt-02', 'management-tools', 'Which tool gives you a browser-accessible shell, with Bash or PowerShell, and needs no local installation?', '["Azure Cloud Shell", "Azure File Sync", "Azure Advisor", "Azure Pricing Calculator"]'::jsonb, 0, 'Azure Cloud Shell is an authenticated shell you open from the browser. It comes with the Azure CLI and Azure PowerShell already available.', 2),
  ('mt-03', 'management-tools', 'Which statement about Azure CLI and Azure PowerShell is correct?', '["They are both command-line tools that can automate Azure tasks, using az commands and cmdlets such as New-AzVM respectively", "Only Azure CLI can create virtual machines", "They only work from the portal", "Azure PowerShell can only run on Windows Server"]'::jsonb, 0, 'Both can create and manage resources and be scripted. Azure CLI uses az commands. Azure PowerShell uses cmdlets such as New-AzVM. Both run on Windows, macOS and Linux.', 2),
  ('mt-04', 'management-tools', 'Which service extends Azure management to servers and Kubernetes clusters running outside Azure, such as on-premises or in other clouds?', '["Azure Arc", "Azure Advisor", "Azure Files", "Azure Policy"]'::jsonb, 0, 'Azure Arc projects non-Azure resources into Azure so you can manage and govern them with the same tools, policies and RBAC.', 2),
  ('mt-05', 'management-tools', 'What is the main benefit of infrastructure as code (IaC)?', '["Repeatable, consistent deployments defined in code that can be version-controlled", "It removes the need for any security", "It makes resources free", "It only works for on-premises servers"]'::jsonb, 0, 'IaC describes infrastructure in files, so deployments are repeatable, reviewable, testable and consistent. It reduces manual configuration errors.', 2),
  ('mt-06', 'management-tools', 'Which statement describes Azure Resource Manager (ARM)?', '["A tool for estimating costs", "The deployment and management service that provides a consistent management layer for all Azure tools, including the portal and CLI", "A type of storage account", "A monitoring dashboard"]'::jsonb, 1, 'Whether you use the portal, CLI, PowerShell or an API, your request goes through Azure Resource Manager, which authenticates it, applies RBAC and policy, and carries out the change.', 2),
  ('mt-07', 'management-tools', 'ARM templates are described as idempotent. What does that mean?', '["They can only be deployed once", "Deploying the same template repeatedly produces the same resulting state", "They delete resources after deployment", "They only work in the portal"]'::jsonb, 1, 'ARM templates are declarative: they state the desired result, and redeploying them leaves your environment in that same state. Bicep is a simpler language that compiles to ARM templates.', 3),
  ('mo-01', 'monitoring', 'Which service gives personalised recommendations to improve reliability, security, performance, cost and operational excellence?', '["Azure Advisor", "Azure Service Health", "Azure Cloud Shell", "Azure Data Box"]'::jsonb, 0, 'Azure Advisor analyses your resources and suggests best-practice improvements across those categories.', 1),
  ('mo-02', 'monitoring', 'Where do you find notices about Azure service issues and planned maintenance that affect your resources?', '["Azure Service Health", "Azure Pricing Calculator", "Azure Policy", "AzCopy"]'::jsonb, 0, 'Azure Service Health gives a personalised view of Azure platform incidents, planned maintenance and advisories relevant to the services and regions you use.', 2),
  ('mo-03', 'monitoring', 'Which service collects, analyses and acts on telemetry from both cloud and on-premises environments?', '["Azure Monitor", "Azure DNS", "Azure Migrate", "Azure Files"]'::jsonb, 0, 'Azure Monitor gathers metrics and logs, lets you analyse them, and can raise alerts or trigger automated actions.', 2),
  ('mo-04', 'monitoring', 'Which Azure Monitor tool lets you query log data using the Kusto Query Language (KQL)?', '["Log Analytics", "Azure Advisor", "Azure Resource Locks", "Azure Cloud Shell"]'::jsonb, 0, 'Log Analytics is the tool in the portal for writing and running KQL queries over data stored in Azure Monitor Logs.', 3),
  ('mo-05', 'monitoring', 'Which feature monitors the performance and availability of a web application and helps detect exceptions?', '["Application Insights", "Azure Policy", "Azure Files", "A resource lock"]'::jsonb, 0, 'Application Insights is the application performance monitoring feature of Azure Monitor. It tracks requests, failures, dependencies and user behaviour.', 2),
  ('mo-06', 'monitoring', 'You want an email whenever a VM''s CPU stays above 90% for five minutes. Which feature do you use?', '["Azure Monitor alerts", "A management group", "Azure Data Box", "Azure Reservations"]'::jsonb, 0, 'Azure Monitor alerts evaluate metrics or logs against a condition and notify people or run actions when it is met.', 2)
